{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Didanosine, a purine nucleoside analog, had a median absolute oral bioavailability of 0.19 under fed conditions (range 0.17–0.28 across conditions), demonstrating that polar nucleoside analogs can have low F due to acid lability and first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Acyclovir, a nucleoside analog, is reported with human oral bioavailability of 0.2, providing another example of a polar nucleoside with F at or below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Emtricitabine, a cytidine analog, has high absolute oral bioavailability (93%), but this is attributable to the 5-fluorine that blocks cytidine deaminase; the query (5-azacytidine) lacks this protection and is a known deaminase substrate, so this high-F evidence is mechanistically less applicable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Dapagliflozin, a C-glucoside SGLT2 inhibitor, has 78% oral bioavailability, but its high F reflects a lipophilic aglycone and complete absorption rather than the polar, deaminase-labile ribonucleoside features of the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is 5-azacytidine, a polar ribonucleoside susceptible to cytidine deaminase-mediated first-pass metabolism. Direct nucleoside analog evidence (didanosine F ~0.17–0.28; acyclovir F ~0.2) supports low oral bioavailability. High-F evidence from SGLT2 inhibitors and emtricitabine is mechanistically less applicable because those molecules lack the deaminase liability or are lipophilic C-glucosides. Therefore F is more likely below 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule (5-azacytidine) is present in the provided evidence.",
    "Some records have mismatched SMILES/compound names (e.g., C22 under an AMP-like SMILES but reporting acyclovir), adding uncertainty.",
    "High-F SGLT2 inhibitor evidence is structurally distant from the nucleoside query despite high transfer scores."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

